    /**
     * Tests creating a new OrderAllocation.
     *
     * @return    OrderAllocation
     */
    public OrderAllocation testCreate() throws Throwable {
    OrderAllocation entity = null;

    LOGGER.info( "OrderAllocationTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a OrderAllocation");

    StringBuilder msg = new StringBuilder( "-- Failed to create a OrderAllocation" );

    try {
        entity = service.createOrderAllocation( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getOrderAllocationId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a OrderAllocation with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

