    /**
     * Tests getting all OrderAllocations.
     *
     * @return    Collection
     */
    public List<OrderAllocation> testGetAll() throws Throwable {
    LOGGER.info( "OrderAllocationTest:testGetAll() - Retrieving Collection of OrderAllocations:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all OrderAllocation : " );
    List<OrderAllocation> collection  = null;

    try {
        // call the static get method on the OrderAllocationService
        collection = service.getAllOrderAllocation();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            OrderAllocation currEntity  = null;
            Iterator<OrderAllocation> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getOrderAllocationId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

